INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-northwoods'), 'es', 'title', 'Operación Northwoods');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-northwoods'), 'es', 'subtitle', 'Una propuesta documentada de 1962 de pretextos simulados contra Cuba');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-northwoods'), 'es', 'summary', 'En marzo de 1962, los jefes del Estado Mayor de Estados Unidos propusieron montar o simular ataques que pudieran atribuirse a Cuba para justificar una intervención militar. La propuesta está documentada en un memorando desclasificado. El poder civil no la aprobó y nunca se llevó a cabo.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-northwoods'), 'es', 'background', 'Tras el fracaso de la invasión de bahía de Cochinos (abril de 1961), la administración Kennedy mantuvo la presión encubierta sobre el gobierno cubano en el marco de la operación Mangosta. En ese contexto, los jefes del Estado Mayor enviaron un conjunto de propuestas de pretexto al secretario de Defensa Robert McNamara.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-northwoods') AND position = 0), 'es', 'text', 'Los jefes del Estado Mayor enviaron al secretario de Defensa, el 13 de marzo de 1962, un memorando titulado «Justification for US Military Intervention in Cuba».');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-northwoods') AND position = 1), 'es', 'text', 'Las propuestas incluían incidentes simulados, como un ataque fingido contra un barco estadounidense, incidentes fabricados atribuidos a Cuba y un incidente «Remember the Maine» montado.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-northwoods') AND position = 2), 'es', 'text', 'El plan fue aprobado y se llevó a cabo.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-northwoods') AND position = 2)), 'es', 'text', 'Ningún documento ni testimonio muestra que se ejecutara alguna de las propuestas de Northwoods; el poder civil no las aprobó.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-northwoods') AND position = 3), 'es', 'text', 'Northwoods prueba que desastres posteriores fueron operaciones de «falsa bandera» montadas por el gobierno de Estados Unidos.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-northwoods') AND position = 3)), 'es', 'text', 'Una propuesta de 1962 rechazada no es prueba de ningún otro hecho. Cada afirmación de ese tipo necesita sus propias pruebas independientes.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'mkultra'), 'es', 'title', 'MKUltra');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'mkultra'), 'es', 'subtitle', 'El programa encubierto de la CIA de investigación sobre la modificación de la conducta');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'mkultra'), 'es', 'summary', 'MKUltra fue un programa de investigación de la CIA, aprobado en 1953, que estudió drogas y otros métodos para influir en la conducta humana, incluidos experimentos con personas que no habían dado su consentimiento. Investigaciones oficiales de los años setenta confirmaron su existencia. La mayor parte de sus expedientes se destruyó en 1973.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'mkultra'), 'es', 'background', 'Al comienzo de la Guerra Fría, las agencias estadounidenses temían que los adversarios hubieran desarrollado técnicas de interrogatorio y de «lavado de cerebro». La CIA financió investigación en universidades, hospitales y prisiones, a menudo a través de organizaciones pantalla, en una serie de proyectos de los que MKUltra es el más conocido.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'mkultra') AND position = 0), 'es', 'text', 'La CIA dirigió un programa de investigación llamado MKUltra, aprobado en 1953, que estudió drogas como el LSD y otros métodos de modificación de la conducta.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'mkultra') AND position = 1), 'es', 'text', 'A algunas personas se les administraron drogas sin su conocimiento ni consentimiento, entre ellas el científico Frank Olson, que murió en 1953.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'mkultra') AND position = 2), 'es', 'text', 'La mayor parte de los expedientes de MKUltra se destruyó en 1973 por orden del director de la CIA Richard Helms.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'mkultra') AND position = 3), 'es', 'text', 'La CIA habría logrado crear agentes «controlados mentalmente» de forma fiable.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'mkultra') AND position = 3)), 'es', 'text', 'Los expedientes conservados y los testimonios oficiales describen una investigación con resultados limitados e irregulares. Ninguna prueba documentada muestra que se lograra un control mental fiable.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'watergate'), 'es', 'title', 'Watergate');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'watergate'), 'es', 'subtitle', 'Una conspiración política documentada que acabó con una presidencia');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'watergate'), 'es', 'summary', 'El allanamiento de 1972 en las oficinas del Comité Nacional Demócrata, en el complejo Watergate, y el encubrimiento posterior llevaron a la dimisión del presidente Richard Nixon en agosto de 1974. Watergate es una conspiración política establecida por los tribunales, el Congreso y las grabaciones de la Casa Blanca.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'watergate'), 'es', 'background', 'Durante la campaña presidencial de 1972, agentes vinculados al comité para la reelección del presidente realizaron espionaje y sabotaje contra adversarios políticos. La detención de cinco intrusos el 17 de junio de 1972 inició investigaciones de periodistas, un fiscal especial, un gran jurado federal y el Senado.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'watergate') AND position = 0), 'es', 'text', 'El 17 de junio de 1972 detuvieron a cinco hombres dentro de las oficinas del Comité Nacional Demócrata, en el complejo Watergate.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'watergate') AND position = 1), 'es', 'text', 'Los intrusos estaban vinculados al comité para la reelección del presidente.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'watergate') AND position = 2), 'es', 'text', 'El presidente Nixon participó en el encubrimiento, como muestra la conversación grabada del 23 de junio de 1972 (la cinta llamada «smoking gun»).');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'watergate') AND position = 3), 'es', 'text', 'El Tribunal Supremo ordenó por unanimidad la entrega de las cintas de la Casa Blanca en United States v. Nixon (1974).');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'watergate') AND position = 4), 'es', 'text', 'La fuente confidencial del Washington Post, «Deep Throat», era el director adjunto del FBI Mark Felt.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'watergate') AND position = 5), 'es', 'text', 'El allanamiento habría servido a fines ocultos distintos del espionaje político y lo habrían dirigido otros iniciados.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'watergate') AND position = 5)), 'es', 'text', 'Estos relatos revisionistas están en disputa, se apoyan en testimonios discutidos y fueron objeto de una demanda por difamación del antiguo asesor de la Casa Blanca John Dean.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'area-51'), 'es', 'title', 'Área 51');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'area-51'), 'es', 'subtitle', 'Un centro de pruebas secreto real y las afirmaciones extraterrestres que lo rodean');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'area-51'), 'es', 'summary', 'El Área 51, en Groom Lake (Nevada), es un centro de pruebas real y durante mucho tiempo secreto, usado para desarrollar aviones de reconocimiento como el U-2 y el A-12 OXCART; su existencia se reconoció oficialmente en 2013. Las afirmaciones de que allí se guardan o estudian naves extraterrestres siguen sin verificar.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'area-51'), 'es', 'background', 'En 1955, la CIA y la Fuerza Aérea eligieron el lecho seco y remoto de Groom Lake como lugar de pruebas del avión espía U-2. Programas posteriores, entre ellos el A-12 OXCART, también se probaron allí. El secreto estricto en torno a la base alimentó las especulaciones.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'area-51') AND position = 0), 'es', 'text', 'Un centro de pruebas secreto en Groom Lake (Nevada) fue usado por la CIA y la Fuerza Aérea para desarrollar y probar aviones de reconocimiento como el U-2 y el A-12 OXCART.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'area-51') AND position = 1), 'es', 'text', 'El gobierno de Estados Unidos reconoció oficialmente el lugar en 2013, al publicar una historia desclasificada de la CIA.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'area-51') AND position = 2), 'es', 'text', 'Los vuelos secretos de reconocimiento a gran altitud explican una parte importante de los avisos de ovnis de los años cincuenta y sesenta.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'area-51') AND position = 3), 'es', 'text', 'En el Área 51 o en sus inmediaciones se guardarían o estudiarían naves o seres extraterrestres.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'area-51') AND position = 3)), 'es', 'text', 'No se ha presentado ninguna prueba verificable. Una revisión del Departamento de Defensa de 2024 no halló pruebas de que ningún programa del gobierno de Estados Unidos tuviera tecnología extraterrestre. No se pudieron confirmar las credenciales académicas alegadas del testigo más conocido.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'moon-landing-conspiracy-theory'), 'es', 'title', 'Teoría de la conspiración del alunizaje');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'moon-landing-conspiracy-theory'), 'es', 'subtitle', 'La afirmación de que los alunizajes del Apolo fueron un montaje');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'moon-landing-conspiracy-theory'), 'es', 'summary', 'La afirmación de que la NASA escenificó los alunizajes del Apolo (1969-1972) apareció en los años setenta. La contradicen abundantes pruebas independientes, entre ellas muestras lunares traídas, retrorreflectores que aún se usan para telemetría láser, el seguimiento independiente de las misiones e imágenes orbitales de los lugares de alunizaje.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'moon-landing-conspiracy-theory'), 'es', 'background', 'Entre 1969 y 1972, seis misiones Apolo posaron a doce astronautas en la Luna. El programa se desarrolló durante la carrera espacial de la Guerra Fría con la Unión Soviética, que seguía las misiones de cerca.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'moon-landing-conspiracy-theory') AND position = 0), 'es', 'text', 'El Apolo 11 alunizó el 20 de julio de 1969 y devolvió a su tripulación sana y salva a la Tierra.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'moon-landing-conspiracy-theory') AND position = 1), 'es', 'text', 'Los alunizajes se habrían rodado en un estudio.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'moon-landing-conspiracy-theory') AND position = 1)), 'es', 'text', 'Los retrorreflectores colocados por las tripulaciones del Apolo se siguen usando para telemetría láser, científicos de todo el mundo han estudiado las muestras lunares y cámaras en órbita han fotografiado el material de alunizaje y las huellas de los astronautas.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'moon-landing-conspiracy-theory') AND position = 2), 'es', 'text', 'Las fotografías mostrarían incoherencias (sin estrellas, una bandera que «ondea», sombras no paralelas) que probarían el fraude.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'moon-landing-conspiracy-theory') AND position = 2)), 'es', 'text', 'Las exposiciones cortas para la superficie lunar, muy brillante, no captan estrellas tenues; la bandera se sostenía con una barra horizontal y solo se movía al manipularla; las sombras divergen por la perspectiva y el terreno irregular.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'illuminati-narratives'), 'es', 'title', 'Relatos sobre los Illuminati');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'illuminati-narratives'), 'es', 'subtitle', 'De una sociedad bávara del siglo XVIII a un mito mundial');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'illuminati-narratives'), 'es', 'summary', 'La orden de los Illuminati fue una sociedad secreta real de la Ilustración, fundada en Baviera en 1776 y suprimida hacia 1785. Las afirmaciones de que sobrevivió y controla en secreto los acontecimientos del mundo no están respaldadas.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'illuminati-narratives'), 'es', 'background', 'Adam Weishaupt, profesor de la universidad de Ingolstadt, fundó la orden para promover las ideas de la Ilustración frente a la influencia de la Iglesia y del absolutismo. Reclutaba entre la élite instruida, en parte a través de logias masónicas, antes de que el elector Karl Theodor prohibiera las sociedades secretas no autorizadas.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'illuminati-narratives') AND position = 0), 'es', 'text', 'La orden de los Illuminati fue fundada en Ingolstadt (Baviera) el 1 de mayo de 1776 por Adam Weishaupt.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'illuminati-narratives') AND position = 1), 'es', 'text', 'El gobierno bávaro prohibió la orden en 1785.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'illuminati-narratives') AND position = 2), 'es', 'text', 'Los Illuminati habrían sobrevivido en secreto y orquestado la Revolución francesa.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'illuminati-narratives') AND position = 2)), 'es', 'text', 'Los historiadores no han hallado pruebas de que la orden siguiera activa tras su supresión. La Revolución francesa tiene causas políticas, sociales y económicas ampliamente documentadas.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'illuminati-narratives') AND position = 3), 'es', 'text', 'Los Illuminati controlarían hoy los gobiernos, las finanzas o la industria del entretenimiento.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'illuminati-narratives') AND position = 3)), 'es', 'text', 'Ninguna prueba creíble respalda esta afirmación. El relato está construido para ser irrefutable y se ha usado repetidamente para difundir mitos conspirativos antisemitas.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'chemtrail-claims'), 'es', 'title', 'Afirmaciones sobre los chemtrails');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'chemtrail-claims'), 'es', 'subtitle', 'La creencia de que las estelas de los aviones son fumigaciones secretas');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'chemtrail-claims'), 'es', 'summary', 'Las afirmaciones sobre los chemtrails sostienen que las estelas duraderas detrás de los aviones son agentes químicos o biológicos rociados a propósito. La ciencia de la atmósfera explica las estelas persistentes como estelas de condensación. Una encuesta de 2016 a 77 expertos no halló pruebas de un programa secreto de fumigación a gran escala.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'chemtrail-claims'), 'es', 'background', 'Los motores de los aviones emiten vapor de agua y partículas. En el aire frío y húmedo a la altitud de crucero, ese vapor se condensa y se congela en cristales de hielo, y forma estelas que pueden persistir y extenderse como nubes parecidas a los cirros.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'chemtrail-claims') AND position = 0), 'es', 'text', 'Los aviones producen estelas de condensación que pueden persistir y extenderse durante horas cuando la alta atmósfera está fría y húmeda.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'chemtrail-claims') AND position = 1), 'es', 'text', 'Las estelas persistentes serían sustancias químicas rociadas a propósito como parte de un programa secreto a gran escala.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'chemtrail-claims') AND position = 1)), 'es', 'text', 'En una encuesta revisada por pares, 76 de 77 químicos de la atmósfera y geoquímicos declararon no haber encontrado pruebas de un programa secreto de fumigación a gran escala; lo presentado como prueba se explicaba por otros factores.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'chemtrail-claims') AND position = 2), 'es', 'text', 'La geoingeniería solar, como inyectar aerosoles en la estratosfera, se ha propuesto en la literatura científica.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'chemtrail-claims') AND position = 2)), 'es', 'text', 'Se trata de propuestas y evaluaciones de investigación. No está documentado ningún despliegue secreto a gran escala.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives'), 'es', 'title', 'Relatos conspirativos sobre JFK');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives'), 'es', 'subtitle', 'Versiones enfrentadas del asesinato de 1963');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives'), 'es', 'summary', 'El presidente John F. Kennedy fue asesinado en Dallas el 22 de noviembre de 1963. La Comisión Warren (1964) concluyó que Lee Harvey Oswald actuó solo. El comité especial de la Cámara sobre asesinatos (1979) concluyó que Kennedy probablemente fue asesinado como resultado de una conspiración, hallazgo basado en gran parte en pruebas acústicas que la Academia Nacional de Ciencias discutió en 1982.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives'), 'es', 'background', 'Oswald fue detenido el día del asesinato y Jack Ruby lo mató a tiros dos días después, así que no hubo juicio. Los huecos del expediente público y los archivos clasificados durante mucho tiempo alimentaron décadas de teorías alternativas.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives') AND position = 0), 'es', 'text', 'Kennedy fue asesinado a tiros en Dealey Plaza (Dallas) el 22 de noviembre de 1963.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives') AND position = 1), 'es', 'text', 'La Comisión Warren concluyó que Lee Harvey Oswald disparó y actuó solo.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives') AND position = 2), 'es', 'text', 'El HSCA concluyó en 1979 que Kennedy probablemente fue asesinado como resultado de una conspiración.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives') AND position = 3), 'es', 'text', 'Un segundo tirador habría disparado desde la «colina cubierta de hierba».');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives') AND position = 3)), 'es', 'text', 'El comité de acústica balística de la Academia Nacional de Ciencias concluyó en 1982 que las pruebas acústicas no mostraban un disparo desde la colina.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives') AND position = 4), 'es', 'text', 'La CIA, el crimen organizado u otros grupos habrían planeado el asesinato.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'jfk-related-conspiracy-narratives') AND position = 4)), 'es', 'text', 'Ninguna investigación oficial ha producido pruebas verificadas de esto. El HSCA halló que la CIA, el FBI y el Servicio Secreto no estaban implicados, aunque no pudo descartar la participación de miembros aislados de ciertos grupos.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study'), 'es', 'title', 'Estudio de Tuskegee sobre la sífilis');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study'), 'es', 'subtitle', 'Cuarenta años de tratamiento denegado por el Servicio de Salud Pública de Estados Unidos');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study'), 'es', 'summary', 'De 1932 a 1972, el Servicio de Salud Pública de Estados Unidos observó el curso de la sífilis no tratada en hombres negros del condado de Macon (Alabama). No se les dijo el diagnóstico ni se les trató, ni siquiera después de que la penicilina se convirtiera en el remedio habitual. El estudio terminó cuando la prensa lo reveló en 1972.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study'), 'es', 'background', 'Participaron unos 600 hombres: unos 400 con sífilis y unos 200 sin ella, como grupo de control. Se les dijo que los trataban de «mala sangre» y recibían comidas gratuitas, reconocimientos y un seguro de entierro. Los investigadores procuraron que no recibieran tratamiento en otro sitio.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study') AND position = 0), 'es', 'text', 'El Servicio de Salud Pública observó la sífilis no tratada en unos 600 hombres negros de Alabama de 1932 a 1972, sin su consentimiento informado.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study') AND position = 1), 'es', 'text', 'El tratamiento se siguió negando incluso después de que la penicilina se convirtiera, en los años cuarenta, en el remedio habitual de la sífilis.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study') AND position = 2), 'es', 'text', 'El escándalo llevó a nuevas reglas para la investigación con seres humanos, entre ellas la National Research Act de 1974 y el informe Belmont de 1979.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study') AND position = 3), 'es', 'text', 'A los hombres del estudio de Tuskegee se les habría infectado deliberadamente con sífilis.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study') AND position = 3)), 'es', 'text', 'Los hombres ya tenían sífilis cuando fueron reclutados. La infección deliberada sí ocurrió en otros experimentos del Servicio de Salud Pública, en Guatemala, de 1946 a 1948.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'cointelpro'), 'es', 'title', 'COINTELPRO');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'cointelpro'), 'es', 'subtitle', 'Los programas secretos del FBI contra grupos políticos dentro de Estados Unidos');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'cointelpro'), 'es', 'summary', 'De 1956 a 1971, el FBI llevó a cabo una serie de programas de contrainteligencia, conocidos como COINTELPRO, para vigilar, infiltrar, desacreditar y perturbar organizaciones políticas dentro de Estados Unidos. Los programas se hicieron públicos después de que activistas robaran expedientes de una oficina del FBI en 1971, y el comité Church los documentó en detalle.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'cointelpro'), 'es', 'background', 'El primer programa, iniciado en 1956, se dirigió contra el Partido Comunista de Estados Unidos. Programas posteriores apuntaron al Socialist Workers Party, a grupos supremacistas blancos, a organizaciones nacionalistas negras y de derechos civiles, y a la Nueva Izquierda. Los métodos incluían cartas anónimas, noticias de prensa colocadas, informantes e intentos de provocar conflictos entre grupos.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'cointelpro') AND position = 0), 'es', 'text', 'El FBI mantuvo de 1956 a 1971 programas de contrainteligencia para vigilar, infiltrar, desacreditar y perturbar organizaciones políticas dentro del país.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'cointelpro') AND position = 1), 'es', 'text', 'Los programas se conocieron tras el robo de expedientes en la oficina del FBI de Media (Pensilvania) en marzo de 1971.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'cointelpro') AND position = 2), 'es', 'text', 'En 1964, el FBI envió a Martin Luther King Jr. una carta anónima que él y sus asesores leyeron como una incitación al suicidio.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'cointelpro') AND position = 3), 'es', 'text', 'COINTELPRO nunca habría terminado de verdad y continuaría igual hoy.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'cointelpro') AND position = 3)), 'es', 'text', 'Los programas terminaron oficialmente en 1971, y después se crearon normas de control y comisiones de inteligencia en el Congreso. Las afirmaciones sobre operaciones posteriores deben juzgarse por sus propias pruebas.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'es', 'title', 'Incidente del golfo de Tonkín');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'es', 'subtitle', 'El ataque que no ocurrió y la resolución que siguió');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'es', 'summary', 'En agosto de 1964, Estados Unidos informó de dos ataques de lanchas norvietnamitas contra destructores estadounidenses en el golfo de Tonkín. El primero, el 2 de agosto, ocurrió. El segundo, informado el 4 de agosto, casi con seguridad no ocurrió. Aun así, el Congreso aprobó la resolución del golfo de Tonkín, que se convirtió en la base jurídica de la escalada de la guerra de Vietnam.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'es', 'background', 'El 2 de agosto de 1964, el destructor USS Maddox, en una patrulla de inteligencia, fue atacado por tres lanchas torpederas norvietnamitas. En la noche del 4 de agosto, el Maddox y el USS Turner Joy informaron de un segundo ataque con mal tiempo. El presidente Johnson ordenó ataques aéreos al día siguiente, y el 7 de agosto el Congreso aprobó la resolución con solo dos votos en contra en el Senado.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 0), 'es', 'text', 'El 2 de agosto de 1964, lanchas torpederas norvietnamitas atacaron al destructor USS Maddox en el golfo de Tonkín.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 1), 'es', 'text', 'El segundo ataque informado el 4 de agosto de 1964 no ocurrió.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 2), 'es', 'text', 'El Congreso aprobó la resolución del golfo de Tonkín el 7 de agosto de 1964; autorizaba al presidente a usar la fuerza armada en el Sudeste Asiático.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 3), 'es', 'text', 'Responsables estadounidenses habrían inventado a sabiendas el ataque del 4 de agosto como pretexto para la guerra.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 3)), 'es', 'text', 'El estudio de la NSA muestra que la inteligencia de señales se manejó mal y se presentó de forma selectiva. Los historiadores no coinciden en si quienes decidían sabían entonces que no había habido ataque; los primeros informes de los destructores fueron confusos, no inventados.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-paperclip'), 'es', 'title', 'Operación Paperclip');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-paperclip'), 'es', 'subtitle', 'Cómo Estados Unidos reclutó a científicos alemanes después de 1945');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-paperclip'), 'es', 'summary', 'Después de la Segunda Guerra Mundial, Estados Unidos trajo a más de 1.600 científicos, ingenieros y técnicos alemanes en un programa conocido como operación Paperclip. Entre ellos había antiguos miembros del partido nazi y de las SS. A menudo se minimizó su pasado para que pudieran trabajar e inmigrar.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-paperclip'), 'es', 'background', 'El programa lo administraba la Joint Intelligence Objectives Agency. Su objetivo era usar el saber alemán en cohetes, aviación, química y medicina, y sustraerlo a la Unión Soviética. El recluta más conocido fue Wernher von Braun, que había dirigido el programa del cohete V-2 y después dirigió el desarrollo del cohete lunar Saturno V.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-paperclip') AND position = 0), 'es', 'text', 'Estados Unidos reclutó después de 1945 a más de 1.600 científicos, ingenieros y técnicos alemanes, incluidos antiguos miembros del partido nazi y de las SS.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-paperclip') AND position = 1), 'es', 'text', 'Responsables minimizaron u omitieron el pasado nazi de algunos reclutas en sus expedientes para que pudieran inmigrar.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-paperclip') AND position = 2), 'es', 'text', 'El ingeniero de Paperclip Arthur Rudolph, jefe de proyecto del Saturno V, abandonó Estados Unidos en 1984 tras una investigación sobre su papel en la fábrica de trabajo forzado de Mittelwerk.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-paperclip') AND position = 3), 'es', 'text', 'Antiguos nazis habrían controlado en secreto la NASA y habrían seguido a través de ella un plan oculto.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-paperclip') AND position = 3)), 'es', 'text', 'Ingenieros alemanes ocuparon puestos altos, sobre todo en el programa de cohetes de Huntsville, pero la NASA era una agencia civil bajo control político estadounidense. Ninguna prueba muestra un plan oculto.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'roswell-incident'), 'es', 'title', 'Incidente de Roswell');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'roswell-incident'), 'es', 'subtitle', 'Un hallazgo de restos en 1947 y la historia de accidente extraterrestre en que se convirtió');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'roswell-incident'), 'es', 'summary', 'En julio de 1947, las fuerzas aéreas del ejército de Estados Unidos en Roswell (Nuevo México) anunciaron que habían recuperado un «disco volante» y al día siguiente lo corrigieron a un globo meteorológico. Décadas después, el hecho se convirtió en la historia de accidente extraterrestre más conocida. Investigaciones de la Fuerza Aérea en los años noventa relacionaron los restos con el proyecto Mogul, un programa secreto de globos.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'roswell-incident'), 'es', 'background', 'Un ranchero encontró restos de lámina, goma, cinta y palos en un rancho al noroeste de Roswell. El 8 de julio de 1947, la oficina de prensa de Roswell Army Air Field publicó su comunicado del «disco volante»; al día siguiente, el comandante de la Eighth Air Force presentó el material como restos de un globo meteorológico. El proyecto Mogul usaba trenes de globos para escuchar pruebas nucleares soviéticas y entonces era secreto.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 0), 'es', 'text', 'El 8 de julio de 1947, Roswell Army Air Field anunció la recuperación de un «disco volante», y al día siguiente el comunicado fue sustituido por la explicación del globo meteorológico.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 1), 'es', 'text', 'Los restos procedían de un tren de globos secreto del proyecto Mogul.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 2), 'es', 'text', 'Una nave extraterrestre se habría estrellado cerca de Roswell y se habrían recuperado los cuerpos de su tripulación.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 2)), 'es', 'text', 'Dos informes de la Fuerza Aérea y una revisión del Departamento de Defensa de 2024 no hallaron pruebas de una nave extraterrestre. Los relatos de cuerpos aparecieron décadas después y coinciden con pruebas de los años cincuenta con maniquíes antropomorfos y con accidentes sin relación.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 3), 'es', 'text', 'Se destruyeron algunos expedientes administrativos de Roswell Army Air Field de ese periodo.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 4), 'es', 'text', 'Los expedientes destruidos probarían el encubrimiento de un accidente extraterrestre.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 4)), 'es', 'text', 'La General Accounting Office no pudo determinar quién destruyó los expedientes ni por qué. Su pérdida, por sí sola, no prueba qué ocurrió en 1947.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'es', 'title', 'Incendio del Reichstag');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'es', 'subtitle', '¿Quién incendió el parlamento alemán en 1933?');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'es', 'summary', 'En la noche del 27 de febrero de 1933 ardió el edificio del Reichstag en Berlín. El comunista de consejos neerlandés Marinus van der Lubbe fue detenido en el lugar. El nuevo gobierno nazi usó el incendio para suspender derechos fundamentales al día siguiente. Si van der Lubbe actuó solo o si los nazis estuvieron implicados sigue siendo objeto de debate entre los historiadores.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'es', 'background', 'Adolf Hitler había sido nombrado canciller cuatro semanas antes. El 28 de febrero, el presidente Hindenburg firmó el decreto del incendio del Reichstag, que suspendía la libertad de prensa, de reunión y de expresión y permitía detenciones sin juicio. En las semanas siguientes fueron internados miles de comunistas y otros opositores, poco antes de las elecciones del 5 de marzo de 1933.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 0), 'es', 'text', 'El edificio del Reichstag ardió en la noche del 27 de febrero de 1933 y Marinus van der Lubbe fue detenido en su interior.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 1), 'es', 'text', 'Al día siguiente, el decreto del incendio del Reichstag suspendió derechos fundamentales; se usó para perseguir a comunistas y a otros opositores.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 2), 'es', 'text', 'El incendio formaba parte de un levantamiento comunista planeado, como afirmó el gobierno nazi.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 2)), 'es', 'text', 'No se hallaron pruebas de un levantamiento planeado, y el tribunal de Leipzig absolvió en diciembre de 1933 a los cuatro coacusados comunistas.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 3), 'es', 'text', 'Van der Lubbe provocó el incendio solo.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 3)), 'es', 'text', 'Algunos historiadores sostienen que la extensión del incendio y las circunstancias apuntan a cómplices; la cuestión no está zanjada.');
